package com.magicprocamera.ai.recommendation
import com.magicprocamera.ai.scenerecognition.*
import com.magicprocamera.camera.*
data class PhotoRecommendation(val title:String,val settings:ManualSettings,val blurRisk:String,val note:String)
object AiPhotoAdvisor { fun recommend(s:SceneResult,c:CameraCapabilities?):PhotoRecommendation {val r=when(s.scene){Scene.BRIGHT->PhotoRecommendation("Lumière forte",ManualSettings(50,2_000_000,-1,5600),"Faible","Préserve les hautes lumières.");Scene.MOTION->PhotoRecommendation("Action",ManualSettings(400,1_000_000,0,5600),"Moyen","Vitesse rapide recommandée.");Scene.NIGHT->PhotoRecommendation("Nuit",ManualSettings(1600,33_000_000,0,3600),"Élevé","Stabilisez le téléphone.");Scene.LOW_LIGHT->PhotoRecommendation("Faible luminosité",ManualSettings(800,16_000_000,0,4200),"Moyen","Compromis bruit et netteté.");Scene.INTERIOR->PhotoRecommendation("Intérieur",ManualSettings(400,8_000_000,0,4400),"Faible","Réglage neutre.")};return r.copy(settings=r.settings.clamp(c))} }
object AiPhotoAssistant { fun advise(q:String):PhotoRecommendation {val t=q.lowercase();return when{"lune" in t||"étoile" in t->PhotoRecommendation("Ciel étoilé",ManualSettings(800,125_000_000,0,3800,false),"Élevé","Trépied et focus verrouillé conseillés.");"chien" in t||"court" in t||"action" in t->PhotoRecommendation("Action",ManualSettings(640,1_000_000,0,5600),"Moyen","Suivi AF et vitesse rapide.");"coucher" in t||"soleil" in t->PhotoRecommendation("Coucher de soleil",ManualSettings(50,4_000_000,-1,6200),"Faible","Sous-exposez légèrement.");else->PhotoRecommendation("Conseil général",ManualSettings(100,8_000_000,0,5200),"Faible","Vérifiez l'histogramme.")}} }